// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Set the owner to caller so that they can pass the onlyOwner modifier
        vm.prank(address(this));
        c.transferOwnership(caller);

        bool ok;
        address ownerBefore = c.owner();
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        // If the call succeeded, the owner must remain unchanged.
        // The bug sets owner = address(0) inside owned(), so it changes on success.
        assertTrue(!ok || c.owner() == ownerBefore);
    }
}

